def concatenated_divisibility(nums, k):
    from functools import lru_cache

    n = len(nums)
    nums = sorted(nums)                          # ascending, so the first feasible pick is the lexicographically smallest
    pow10 = [pow(10, len(str(x)), k) for x in nums]   # 10^len(x) mod k
    full = (1 << n) - 1

    @lru_cache(None)
    def can(mask, mod):
        # can the numbers not in mask be appended so the whole concatenation is divisible by k?
        if mask == full:
            return mod == 0
        for i in range(n):
            if not (mask >> i) & 1:
                if can(mask | (1 << i), (mod * pow10[i] + nums[i]) % k):
                    return True
        return False

    if not can(0, 0):
        return []

    # Reconstruct greedily: take the smallest number that still leaves a feasible completion
    res, mask, mod = [], 0, 0
    for _ in range(n):
        for i in range(n):
            if not (mask >> i) & 1:
                nm = (mod * pow10[i] + nums[i]) % k
                if can(mask | (1 << i), nm):
                    res.append(nums[i])
                    mask |= 1 << i
                    mod = nm
                    break
    return res
